const { chromium } = require('playwright-core');
const path = require('path');
const fs = require('fs');

async function renderPoster() {
    const browser = await chromium.launch({
        headless: true,
        executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined
    });
    const page = await browser.newPage();

    const htmlPath = path.resolve(__dirname, 'Web-Summit-Lisbon-2026-infographic.html');
    await page.goto(`file://${htmlPath}`);

    // Wait for the infographic to render
    await page.waitForTimeout(3000);

    // Take a screenshot
    const screenshot = await page.screenshot({
        type: 'png',
        fullPage: true
    });

    const outputPath = path.resolve(__dirname, 'final_poster.png');
    fs.writeFileSync(outputPath, screenshot);

    await browser.close();
    console.log('Poster saved to:', outputPath);
}

renderPoster().catch(console.error);

